=<!DOCTYPE html>
<html lang="pt-BR">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Conectar WhatsApp — UpvIA Agentes</title>
<link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap" rel="stylesheet">
<style>
  :root {
    --green-primary: #00a884;
    --green-dark: #008f72;
    --green-light: #d9fdd3;
    --bg-dark: #0b141a;
    --bg-card: #111b21;
    --bg-input: #1a2730;
    --text-primary: #e9edef;
    --text-secondary: #8696a0;
    --border-color: #233138;
    --accent: #00cf9d;
    --danger: #f15c6d;
    --warning: #f7c948;
  }
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body {
    font-family: 'Plus Jakarta Sans', sans-serif;
    background: var(--bg-dark);
    color: var(--text-primary);
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 20px;
    position: relative;
    overflow-x: hidden;
  }
  body::before {
    content: '';
    position: fixed;
    top: 0; left: 0; right: 0;
    height: 260px;
    background: linear-gradient(135deg, var(--green-primary) 0%, #006d5b 100%);
    z-index: 0;
  }
  .container {
    position: relative;
    z-index: 1;
    width: 100%;
    max-width: 480px;
  }
  .logo-area {
    text-align: center;
    margin-bottom: 24px;
  }
  .logo-area h1 {
    font-size: 28px;
    font-weight: 800;
    color: #fff;
    letter-spacing: -0.5px;
  }
  .logo-area h1 span {
    color: var(--green-light);
    font-weight: 600;
  }
  .logo-area p {
    color: rgba(255,255,255,0.8);
    font-size: 14px;
    margin-top: 4px;
  }
  .card {
    background: var(--bg-card);
    border-radius: 16px;
    border: 1px solid var(--border-color);
    overflow: hidden;
    box-shadow: 0 20px 60px rgba(0,0,0,0.4);
  }
  .card-header {
    padding: 24px 28px 16px;
    border-bottom: 1px solid var(--border-color);
  }
  .card-header h2 {
    font-size: 18px;
    font-weight: 700;
    margin-bottom: 6px;
  }
  .card-header p {
    font-size: 13px;
    color: var(--text-secondary);
    line-height: 1.5;
  }
  .negocio-badge {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    background: var(--bg-input);
    border: 1px solid var(--border-color);
    border-radius: 8px;
    padding: 8px 14px;
    margin-top: 12px;
    font-size: 13px;
    font-weight: 600;
    color: var(--accent);
  }
  .qr-section {
    padding: 28px;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 20px;
  }
  .qr-wrapper {
    position: relative;
    width: 264px;
    height: 264px;
    background: #fff;
    border-radius: 12px;
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;
  }
  .qr-wrapper img {
    width: 248px;
    height: 248px;
    object-fit: contain;
  }
  .qr-wrapper.loading img { display: none; }
  .qr-wrapper .spinner {
    display: none;
    width: 48px;
    height: 48px;
    border: 4px solid #e0e0e0;
    border-top-color: var(--green-primary);
    border-radius: 50%;
    animation: spin 0.8s linear infinite;
  }
  .qr-wrapper.loading .spinner { display: block; }
  .qr-wrapper .expired-overlay {
    display: none;
    position: absolute;
    inset: 0;
    background: rgba(255,255,255,0.95);
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 12px;
  }
  .qr-wrapper.expired .expired-overlay { display: flex; }
  .qr-wrapper.expired img { filter: blur(4px); opacity: 0.3; }
  .expired-icon {
    width: 48px;
    height: 48px;
    border-radius: 50%;
    background: var(--danger);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 24px;
    color: #fff;
  }
  .expired-text {
    color: #333;
    font-size: 14px;
    font-weight: 600;
  }
  .status-bar {
    width: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    padding: 10px 16px;
    border-radius: 10px;
    font-size: 13px;
    font-weight: 600;
  }
  .status-bar.waiting {
    background: rgba(0,168,132,0.12);
    color: var(--accent);
  }
  .status-bar.expired {
    background: rgba(241,92,109,0.12);
    color: var(--danger);
  }
  .status-bar.connected {
    background: rgba(0,207,157,0.12);
    color: var(--accent);
  }
  .status-bar.error {
    background: rgba(241,92,109,0.12);
    color: var(--danger);
  }
  .status-dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: currentColor;
    animation: pulse-dot 1.5s ease-in-out infinite;
  }
  .status-bar.expired .status-dot,
  .status-bar.error .status-dot { animation: none; }
  .timer-bar {
    width: 100%;
    height: 3px;
    background: var(--bg-input);
    border-radius: 2px;
    overflow: hidden;
  }
  .timer-bar-fill {
    height: 100%;
    background: var(--accent);
    border-radius: 2px;
    transition: width 1s linear;
  }
  .btn-refresh {
    width: 100%;
    padding: 14px;
    border: none;
    border-radius: 10px;
    background: var(--green-primary);
    color: #fff;
    font-family: inherit;
    font-size: 15px;
    font-weight: 700;
    cursor: pointer;
    transition: all 0.2s;
    display: none;
  }
  .btn-refresh:hover { background: var(--green-dark); transform: translateY(-1px); }
  .btn-refresh:active { transform: translateY(0); }
  .btn-refresh.show { display: block; }
  .steps-section {
    padding: 0 28px 28px;
  }
  .steps-title {
    font-size: 14px;
    font-weight: 700;
    color: var(--text-secondary);
    text-transform: uppercase;
    letter-spacing: 1px;
    margin-bottom: 16px;
  }
  .step {
    display: flex;
    gap: 14px;
    margin-bottom: 14px;
  }
  .step-num {
    flex-shrink: 0;
    width: 28px;
    height: 28px;
    border-radius: 50%;
    background: var(--bg-input);
    border: 1px solid var(--border-color);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 12px;
    font-weight: 700;
    color: var(--accent);
  }
  .step-text {
    font-size: 13px;
    color: var(--text-secondary);
    line-height: 1.5;
    padding-top: 3px;
  }
  .step-text strong {
    color: var(--text-primary);
  }
  .tip-box {
    margin: 0 28px 28px;
    padding: 14px 16px;
    background: rgba(247,201,72,0.08);
    border: 1px solid rgba(247,201,72,0.2);
    border-radius: 10px;
    font-size: 13px;
    color: var(--warning);
    line-height: 1.5;
  }
  .connected-screen {
    display: none;
    padding: 48px 28px;
    text-align: center;
  }
  .connected-screen.show { display: block; }
  .connected-icon {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    background: linear-gradient(135deg, var(--green-primary), var(--accent));
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 40px;
    margin: 0 auto 20px;
    box-shadow: 0 8px 32px rgba(0,207,157,0.3);
  }
  .connected-screen h2 {
    font-size: 22px;
    font-weight: 800;
    margin-bottom: 8px;
  }
  .connected-screen p {
    font-size: 14px;
    color: var(--text-secondary);
    line-height: 1.6;
  }
  .footer-text {
    text-align: center;
    margin-top: 20px;
    font-size: 12px;
    color: var(--text-secondary);
  }
  @keyframes spin {
    to { transform: rotate(360deg); }
  }
  @keyframes pulse-dot {
    0%, 100% { opacity: 1; }
    50% { opacity: 0.3; }
  }
  @media (max-width: 500px) {
    .card-header { padding: 20px 20px 14px; }
    .qr-section { padding: 20px; }
    .steps-section { padding: 0 20px 20px; }
    .tip-box { margin: 0 20px 20px; }
    .qr-wrapper { width: 232px; height: 232px; }
    .qr-wrapper img { width: 216px; height: 216px; }
  }
</style>
</head>
<body>
<div class="container">
  <div class="logo-area">
    <h1>Upv<span>IA</span> Agentes</h1>
    <p>Conecte seu WhatsApp para ativar sua atendente</p>
  </div>
  <div class="card">
    <div class="card-header">
      <h2>📱 Conectar WhatsApp</h2>
      <p>Escaneie o QR Code abaixo para vincular seu WhatsApp à sua atendente inteligente.</p>
      <div class="negocio-badge" id="negocioBadge">
        🏪 <span id="nomeNegocio">Carregando...</span>
      </div>
    </div>
    <div class="qr-section" id="qrSection">
      <div class="qr-wrapper loading" id="qrWrapper">
        <div class="spinner"></div>
        <img id="qrImage" src="" alt="QR Code WhatsApp" />
        <div class="expired-overlay">
          <div class="expired-icon">⏰</div>
          <div class="expired-text">QR Code expirado</div>
        </div>
      </div>
      <div class="timer-bar" id="timerBar">
        <div class="timer-bar-fill" id="timerFill" style="width: 100%"></div>
      </div>
      <div class="status-bar waiting" id="statusBar">
        <div class="status-dot"></div>
        <span id="statusText">Gerando QR Code...</span>
      </div>
      <button class="btn-refresh" id="btnRefresh" onclick="gerarNovoQR()">
        🔄 Gerar novo QR Code
      </button>
    </div>
    <div class="steps-section" id="stepsSection">
      <div class="steps-title">Como conectar</div>
      <div class="step">
        <div class="step-num">1</div>
        <div class="step-text"><strong>Envie este link</strong> para alguém próximo a você (pode ser pelo próprio WhatsApp)</div>
      </div>
      <div class="step">
        <div class="step-num">2</div>
        <div class="step-text">A pessoa abre o link em <strong>outra tela</strong> (celular ou computador)</div>
      </div>
      <div class="step">
        <div class="step-num">3</div>
        <div class="step-text">No <strong>seu celular</strong>, abra o WhatsApp → <strong>Dispositivos conectados</strong> → <strong>Conectar um dispositivo</strong></div>
      </div>
      <div class="step">
        <div class="step-num">4</div>
        <div class="step-text"><strong>Escaneie o QR Code</strong> que está na outra tela. Pronto! ✨</div>
      </div>
    </div>
    <div class="tip-box">
      💡 <strong>Dica:</strong> Se você está sozinha, abra este link no <strong>navegador do computador</strong> e escaneie com seu celular.
    </div>
    <div class="connected-screen" id="connectedScreen">
      <div class="connected-icon">✅</div>
      <h2>WhatsApp Conectado!</h2>
      <p>Sua atendente inteligente já está ativa e pronta para atender seus clientes. Pode fechar esta página.</p>
    </div>
  </div>
  <p class="footer-text">UpvIA Agentes • Atendimento inteligente para seu negócio</p>
</div>
<script>
  var params = new URLSearchParams(window.location.search);
  var instancia = params.get('i') || '';
  var apikey = params.get('k') || '';
  var negocio = params.get('n') || 'Seu Negócio';
  var EVO_BASE = 'https://evo.upviaagentes.com';
  var QR_DURATION = 40;
  var qrWrapper = document.getElementById('qrWrapper');
  var qrImage = document.getElementById('qrImage');
  var statusBar = document.getElementById('statusBar');
  var statusText = document.getElementById('statusText');
  var btnRefresh = document.getElementById('btnRefresh');
  var timerFill = document.getElementById('timerFill');
  var nomeNegocio = document.getElementById('nomeNegocio');
  var qrSection = document.getElementById('qrSection');
  var stepsSection = document.getElementById('stepsSection');
  var connectedScreen = document.getElementById('connectedScreen');
  var timerInterval = null;
  var checkInterval = null;
  var secondsLeft = QR_DURATION;
  nomeNegocio.textContent = decodeURIComponent(negocio);
  if (!instancia || !apikey) {
    setStatus('error', 'Link inválido. Solicite um novo link.');
    qrWrapper.classList.remove('loading');
  } else {
    gerarNovoQR();
  }
  function gerarNovoQR() {
    clearInterval(timerInterval);
    clearInterval(checkInterval);
    qrWrapper.classList.add('loading');
    qrWrapper.classList.remove('expired');
    btnRefresh.classList.remove('show');
    timerFill.style.width = '100%';
    timerFill.style.background = 'var(--accent)';
    secondsLeft = QR_DURATION;
    setStatus('waiting', 'Gerando QR Code...');
    fetch(EVO_BASE + '/instance/connect/' + instancia, {
      method: 'GET',
      headers: { 'apikey': apikey }
    })
    .then(function(res) { return res.json(); })
    .then(function(data) {
      if (data.instance && data.instance.state === 'open') {
        mostrarConectado();
        return;
      }
      var qrBase64 = null;
      if (data.base64) {
        qrBase64 = data.base64;
      } else if (data.qrcode && data.qrcode.base64) {
        qrBase64 = data.qrcode.base64;
      }
      if (!qrBase64) {
        qrBase64 = findBase64(data);
      }
      if (qrBase64) {
        if (qrBase64.indexOf('data:image') !== 0) {
          qrBase64 = 'data:image/png;base64,' + qrBase64;
        }
        qrImage.src = qrBase64;
        qrWrapper.classList.remove('loading');
        setStatus('waiting', 'Aguardando escaneamento...');
        iniciarTimer();
        iniciarVerificacaoConexao();
      } else {
        setStatus('error', 'Não foi possível gerar o QR. Tente novamente.');
        qrWrapper.classList.remove('loading');
        btnRefresh.classList.add('show');
      }
    })
    .catch(function(err) {
      console.error('Erro:', err);
      setStatus('error', 'Erro de conexão. Tente novamente.');
      qrWrapper.classList.remove('loading');
      btnRefresh.classList.add('show');
    });
  }
  function findBase64(obj, depth) {
    depth = depth || 0;
    if (!obj || depth > 4) return null;
    if (typeof obj === 'string' && obj.indexOf('data:image') === 0) return obj;
    if (typeof obj === 'string' && obj.length > 200 && /^[A-Za-z0-9+\/=]+$/.test(obj.substring(0, 50))) return obj;
    if (typeof obj !== 'object') return null;
    var keys = ['base64', 'qrcode', 'qr', 'qrOrCode', 'code'];
    for (var i = 0; i < keys.length; i++) {
      if (obj[keys[i]]) {
        var found = findBase64(obj[keys[i]], depth + 1);
        if (found) return found;
      }
    }
    var allKeys = Object.keys(obj);
    for (var j = 0; j < allKeys.length; j++) {
      if (keys.indexOf(allKeys[j]) === -1) {
        var found2 = findBase64(obj[allKeys[j]], depth + 1);
        if (found2) return found2;
      }
    }
    return null;
  }
  function iniciarTimer() {
    timerInterval = setInterval(function() {
      secondsLeft--;
      var pct = (secondsLeft / QR_DURATION) * 100;
      timerFill.style.width = pct + '%';
      if (pct < 30) timerFill.style.background = 'var(--warning)';
      if (pct < 10) timerFill.style.background = 'var(--danger)';
      if (secondsLeft <= 0) {
        clearInterval(timerInterval);
        qrWrapper.classList.add('expired');
        setStatus('expired', 'QR Code expirado. Gere um novo.');
        btnRefresh.classList.add('show');
      }
    }, 1000);
  }
  function iniciarVerificacaoConexao() {
    checkInterval = setInterval(function() {
      fetch(EVO_BASE + '/instance/connectionState/' + instancia, {
        headers: { 'apikey': apikey }
      })
      .then(function(res) { return res.json(); })
      .then(function(data) {
        var state = (data.instance && data.instance.state) || data.state || '';
        if (state === 'open') {
          clearInterval(checkInterval);
          clearInterval(timerInterval);
          mostrarConectado();
        }
      })
      .catch(function() {});
    }, 3000);
  }
  function mostrarConectado() {
    qrSection.style.display = 'none';
    stepsSection.style.display = 'none';
    document.querySelector('.tip-box').style.display = 'none';
    connectedScreen.classList.add('show');
    setStatus('connected', 'Conectado com sucesso!');
  }
  function setStatus(type, text) {
    statusBar.className = 'status-bar ' + type;
    statusText.textContent = text;
  }
</script>
</body>
</html>
